export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult =
  | { premium: number }
  | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
} as const satisfies Record<string, number>;

type InsurableItemType = keyof typeof BASE_PREMIUMS;

const basePremiumOf = (item: Item): number =>
  BASE_PREMIUMS[item.type as InsurableItemType];

/** Premiums are rounded up — in MHPCO's favour. */
const roundPremium = (amount: number): number => Math.ceil(amount);

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

/** Items of a single type, kept together so the block rule can be applied. */
type SameTypeGroup = Item[];

const groupByType = (items: Item[]): SameTypeGroup[] => {
  const groups = new Map<string, SameTypeGroup>();
  for (const item of items) {
    const group = groups.get(item.type) ?? [];
    group.push(item);
    groups.set(item.type, group);
  }
  return [...groups.values()];
};

const sumBasePremiums = (group: SameTypeGroup): number =>
  group.reduce((sum, item) => sum + basePremiumOf(item), 0);

/**
 * Exactly three alike items form a building block priced at a flat premium;
 * any other count is priced per item.
 */
const blockAwareBasePremium = (group: SameTypeGroup): number =>
  group.length === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM
    : sumBasePremiums(group);

const policyBasePremiumFor = (items: Item[]): number =>
  groupByType(items).reduce(
    (sum, group) => sum + blockAwareBasePremium(group),
    0,
  );

const CURSE_SURCHARGE = 0.5;

/** A cursed item is surcharged on its own base premium, not the policy's. */
const curseSurchargeOn = (item: Item): number =>
  item.cursed ? basePremiumOf(item) * CURSE_SURCHARGE : 0;

/** Item-specific modifiers apply to the base premium of the affected item. */
const itemSurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + curseSurchargeOn(item), 0);

const quotePremium = (items: Item[]): number => {
  const policyBasePremium = policyBasePremiumFor(items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE;
  return roundPremium(
    policyBasePremium +
      itemSurcharges(items) +
      firstInsuranceSurcharge +
      PROCESSING_FEE,
  );
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") {
    return { premium: quotePremium(step.items) };
  }
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

