import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Simplest case ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });

  // --- Base premiums per main item type (with 5 G fee, no customer history) ---
  it("single sword, new customer → base 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: false },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("single amulet, new customer → base 60 G + 6 G first insurance + 5 G fee = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "amulet", material: "silver", enchantment: 2, cursed: false },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("single staff, new customer → base 80 G + 8 G first insurance + 5 G fee = 93 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "staff", material: "oak", enchantment: 1, cursed: false },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("single potion, new customer → base 40 G + 4 G first insurance + 5 G fee = 49 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "potion", material: "glass", enchantment: 0, cursed: false },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Components and building blocks of 3 alike ---
  it("1 rune → base premium 25 G (+ 2.5 first insurance + 5 fee = 32.5 → 33 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 33 }] });
  });
  it("2 runes → base premium 50 G (+ 5 first insurance + 5 fee = 60 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("3 runes → base premium 60 G (block applies; + 6 first insurance + 5 fee = 71 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("4 runes → base premium 100 G (no block — block requires exactly 3; + 10 + 5 = 115 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("7 runes → base premium 175 G (+ 17.5 + 5 = 197.5 → 198 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 198 }] });
  });

  // --- "Alike" components (❓ same type, not same family) ---
  it("2 runes + 1 moonstone → base premium 75 G (no block: different types; + 7.5 + 5 = 87.5 → 88 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 88 }] });
  });
  it("3 runes + 3 moonstones → base premium 120 G (two separate blocks; + 12 + 5 = 137 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "moonstone" },
            { type: "moonstone" },
            { type: "moonstone" },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 137 }] });
  });

  // --- Individual premium modifiers ---
  it("cursed sword adds 50 % of the item's base premium (100 + 50 + 10 + 5 = 165 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 3, cursed: true },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 165 }] });
  });
  it("sword with enchantment 5 adds 30 % high-enchantment surcharge (100 + 30 + 10 + 5 = 145 G)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "sword", material: "steel", enchantment: 5, cursed: false },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 145 }] });
  });
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 → both surcharges apply (50 G + 30 G)");
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance carries a 10 % initial assessment surcharge");
  it.todo("second contract of the same customer receives a 15 % follow-up discount");
  it.todo("a 5 G processing fee is added to every premium");

  // --- Modifier scope on multi-item policies (❓ item-specific vs policy-wide) ---
  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (only the sword's base) → 210 G before further modifiers and fee");
  it.todo("policy-wide modifiers apply to the sum of all item base premiums");

  // --- Rounding in the MHPCO's favour ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
  it.todo("deductible applies once per damaged item: sword 500 G + amulet 300 G → payout 600 G");

  // --- Claim: special clauses ---
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Insurance sum and cap ---
  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects premium only)");
  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");

  // --- Cap exhaustion across successive claims ---
  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Multiple items of the same type (❓ two swords) ---
  it.todo("two sword damage entries on a two-sword policy → each entry gets its own deductible");
  it.todo("more damage entries of a type than the policy covers → CLI exits non-zero, claim rejected");

  // --- Error cases ---
  it.todo("quote with an unknown item type → CLI exits non-zero, error on stderr, no results on stdout");
  it.todo("claim referencing an item not part of the policy → CLI exits non-zero with error on stderr");
  it.todo("claim with a damage entry of unknown item type → CLI exits non-zero with error on stderr");
  it.todo("claim with a negative damage amount (-200) → CLI exits non-zero with error on stderr");

  // --- Integration examples ---
  it.todo("newcomer (0 years) with a cursed steel sword (enchantment 3) → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed steel sword (enchantment 7) → premium 160 G");

  // --- CLI end-to-end ---
  it.todo("CLI reads a scenario from stdin and writes a results array of the same length and order to stdout");
  it.todo("CLI schema example: quote amulet then claim 200 G → results [{premium}, {payout, remainingCap}]");
});

