const LOYALTY_DISCOUNT = 0.2;
const LOYALTY_YEARS = 2;

const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS;

/** Policy-wide modifiers apply to the sum of all item base premiums. */
const loyaltyDiscount = (policyBasePremium: number, customer: Customer): number =>
  isLoyal(customer) ? policyBasePremium * LOYALTY_DISCOUNT : 0;

const quotePremium = (items: Item[], customer: Customer): number => {
  const policyBasePremium = policyBasePremiumFor(items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE;
  return roundPremium(
    policyBasePremium +
      itemSurcharges(items) +
      firstInsuranceSurcharge -
      loyaltyDiscount(policyBasePremium, customer) +
      PROCESSING_FEE,
  );
};

const runStep = (step: Step, customer: Customer): StepResult => {
  if (step.op === "quote") {
    return { premium: quotePremium(step.items, customer) };
  }
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
});

