  const policyBasePremium = policyBasePremiumFor(items);
  return roundPremium(
    policyBasePremium +
      policyBasePremium * policyModifierRateFor(customer) +
      itemSurchargesFor(items) +
      PROCESSING_FEE,
  );
};

const runStep = (step: Step, customer: Customer): StepResult => {
  if (step.op === "quote") {
    return { premium: quotePremium(step.items, customer) };
  }
