const INSURANCE_VALUES = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
} as const satisfies Record<InsurableItemType, number>;

const insuranceValueOf = (item: Item): number =>
  INSURANCE_VALUES[item.type as InsurableItemType];

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

/** Payouts are rounded down — in MHPCO's favour. */
const roundPayout = (amount: number): number => Math.floor(amount);

/** A policy created by a quote step, tracked so later claims can draw on it. */
interface Policy {
  items: Item[];
  remainingCap: number;
}

const openPolicy = (items: Item[]): Policy => ({
  items,
  remainingCap:
    CAP_MULTIPLIER * items.reduce((sum, item) => sum + insuranceValueOf(item), 0),
});

const payoutForDamage = (damage: Damage): number =>
  Math.max(0, damage.amount - DEDUCTIBLE);

const settleClaim = (policy: Policy, incident: Incident): StepResult => {
  const desired = incident.damages.reduce(
    (sum, damage) => sum + payoutForDamage(damage),
    0,
  );
  const payout = roundPayout(Math.min(desired, policy.remainingCap));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  let previousContracts = 0;
  const policies = new Map<number, Policy>();

  const results = scenario.steps.map((step, index) => {
    if (step.op === "quote") {
      const context = { customer: scenario.customer, previousContracts };
      previousContracts += 1;
      policies.set(index, openPolicy(step.items));
      return { premium: quotePremium(step.items, context) };
    }

    const policy = policies.get(step.policy);
    if (policy === undefined) {
      throw new Error(`No policy created by step ${step.policy}`);
    }
    return settleClaim(policy, step.incident);
  });

  return { results };
};

